import{_ as r,o as e,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-07-20","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-07-20","date":"2020-07-20T00:00:00.000Z","updated":"2020-07-21T00:00:00.000Z","tags":["Ceph","Orchestrator","Cephadm","Upgrade Experience","Container Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-07-20.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-07-20.md","lastUpdated":1780459816000}'),a={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-07-20.md"};function i(s,t,n,h,c,g){return e(),o("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要-ceph-orchestrator-会议" tabindex="-1">会议纪要：Ceph Orchestrator 会议 <a class="header-anchor" href="#会议纪要-ceph-orchestrator-会议" aria-label="Permalink to &quot;会议纪要：Ceph Orchestrator 会议&quot;">​</a></h3><h4 id="会议时间-2020-07-20" tabindex="-1">会议时间：2020-07-20 <a class="header-anchor" href="#会议时间-2020-07-20" aria-label="Permalink to &quot;会议时间：2020-07-20&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>包模式（Package Mode）问题讨论</strong></p><ul><li><strong>问题描述</strong>：包模式依赖于在所有主机上安装的 <code>cephadm</code> 二进制文件，升级过程复杂，因为对 <code>cephadm</code> 二进制文件的兼容性要求极高。</li><li><strong>讨论内容</strong>：讨论了包模式的升级问题，特别是从 -2 版本升级时，用户更新 <code>cephadm</code> 的时间不确定。</li><li><strong>决定事项</strong>：暂时移除包模式，因为它未被文档化。未来如有需求，可以考虑重新启用。</li></ul></li><li><p><strong>升级用户体验改进</strong></p><ul><li><strong>问题描述</strong>：当前用户在升级集群时需要指定具体的 Ceph 版本。</li><li><strong>讨论内容</strong>：讨论是否需要改进用户体验，例如提供 <code>cephadm upgrade start --latest</code> 选项来更新到最新的次要版本。</li><li><strong>决定事项</strong>：考虑添加 <code>latest</code> 选项，但需要进一步讨论和实现细节。</li></ul></li><li><p><strong>容器挂载问题</strong></p><ul><li><strong>问题描述</strong>：容器停止后，容器挂载未正确刷新。</li><li><strong>讨论内容</strong>：需要进一步调查和解决此问题。</li><li><strong>决定事项</strong>：跟踪问题并寻找解决方案。</li></ul></li><li><p><strong>Cephadm 安装指南</strong></p><ul><li><strong>问题描述</strong>：Zach 计划在本周三前提交 Cephadm 安装指南的 PR。</li><li><strong>讨论内容</strong>：鼓励大家提供反馈。</li><li><strong>决定事项</strong>：Zach 将提交 PR，社区成员提供反馈。</li></ul></li><li><p><strong>Rook 1.4 计划</strong></p><ul><li><strong>问题描述</strong>：Rook 1.4 计划在本月底发布，主要等待 CSI 3.0 发布。</li><li><strong>讨论内容</strong>：无特殊讨论。</li><li><strong>决定事项</strong>：等待 CSI 3.0 发布，计划本月底发布 Rook 1.4。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><p><strong>包模式问题</strong>：</p><ul><li>移除包模式，未来根据需求重新考虑。</li><li>考虑在 Orchestrator 中添加检查，确保所有主机上的 <code>cephadm</code> 版本正确。</li></ul></li><li><p><strong>升级用户体验</strong>：</p><ul><li>讨论并实现 <code>cephadm upgrade start --latest</code> 选项。</li></ul></li><li><p><strong>容器挂载问题</strong>：</p><ul><li>跟踪并解决容器挂载刷新问题。</li></ul></li><li><p><strong>Cephadm 安装指南</strong>：</p><ul><li>Zach 提交 PR，社区成员提供反馈。</li></ul></li><li><p><strong>Rook 1.4 发布</strong>：</p><ul><li>等待 CSI 3.0 发布，计划本月底发布 Rook 1.4。</li></ul></li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议于[具体时间]结束，下次会议将在下周的 Orchestrator 会议中继续讨论。</li></ul>',9)])])}const u=r(a,[["render",i]]);export{p as __pageData,u as default};
